const item = $input.item.json;
const tenant = item.tenant || {};
const sender = item.sender || {};
const msg = item.message || {};

const text = msg.text || item.original_message || item.message || item.text || '';
const number = sender.number || tenant.number || item.number || '521234567890';
const tenantId = tenant.id || item.tenant_id || '';
const tenantName = tenant.name || item.tenant_name || 'Negocio';
const phoneId = tenant.whatsapp_phone_number_id || item.whatsapp_phone_number_id || '10023456789';
const token = tenant.whatsapp_access_token || item.whatsapp_access_token || 'EAAG_DEMO_TOKEN';

return {
  original_message: text,
  wa_number: number,
  tenant_id: tenantId,
  tenant_name: tenantName,
  whatsapp_phone_number_id: phoneId,
  whatsapp_access_token: token,
  tenant: tenant,
  sender: sender
};

const norm = $('Code - Normalize Inbound CRUD Request').item.json;
const rawOutput = $input.item.json.output || $input.item.json.text || '';
const rawMsg = (norm.original_message || '').trim();
const lower = rawMsg.toLowerCase();

let action = '';
let productName = '';
let price = 0;
let stock = 0;
let qtyChange = 0;

// Helper to parse numbers like "500 mil", "500000", "50k", "1.5 millones", "$500.000"
function parseMoney(str) {
  if (!str) return 0;
  let s = str.toLowerCase().replace(/[$ pesos]/g, '').trim();
  if (s.includes('millon') || s.includes('millones')) {
    const num = parseFloat(s.replace(/millon(es)?/g, '').trim());
    return num * 1000000;
  }
  if (s.includes('mil') || s.includes('k')) {
    const num = parseFloat(s.replace(/(mil|k)/g, '').trim());
    return num * 1000;
  }
  if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
    s = s.replace(/\./g, '');
  }
  return parseFloat(s) || 0;
}

// 1. FAST REGEX & NATURAL LANGUAGE PARSER
if (lower === 'ver inventario' || lower === 'inventario' || lower === 'catalogo' || lower === 'catálogo' || lower === 'ver productos' || lower === 'listar' || lower === 'productos') {
  action = 'LIST';
} else if (lower.startsWith('crear producto') || lower.startsWith('agregar producto') || lower.startsWith('nuevo producto') || lower.startsWith('crear ') || lower.startsWith('nuevo ')) {
  action = 'CREATE';

  // Extract Stock: e.g. "stock de 30", "stock 30", "30 unidades", "con 30 unidades"
  const stockMatch = rawMsg.match(/(?:un\s+)?stock\s+(?:de\s+|en\s+)?(\d+)|(?:con\s+)?(\d+)\s+unidades/i);
  if (stockMatch) {
    stock = parseInt(stockMatch[1] || stockMatch[2], 10);
  }

  // Extract Price: e.g. "precio de 500 mil pesos", "precio 50000", "valor 120k", "por 120.000"
  const priceMatch = rawMsg.match(/(?:con\s+)?(?:precio|valor)\s+(?:de\s+|en\s+)?(\d+(?:[.,]\d+)?\s*(?:mil|k|millones|millon)?(?:\s+pesos)?)|(?:por\s+(\d+(?:[.,]\d+)?\s*(?:mil|k|millones|millon)?))/i);
  if (priceMatch) {
    price = parseMoney(priceMatch[1] || priceMatch[2]);
  }

  // Clean product name
  let namePart = rawMsg
    .replace(/^(?:crear|agregar|nuevo)(?:\s+producto)?\s+/i, '')
    .replace(/,?\s*(?:con\s+)?(?:precio|valor)\s+(?:de\s+|en\s+)?\d+(?:[.,]\d+)?\s*(?:mil|k|millones|millon)?(?:\s+pesos)?/gi, '')
    .replace(/,?\s*(?:y\s+)?(?:un\s+)?stock\s+(?:de\s+|en\s+)?\d+(?:\s+unidades)?/gi, '')
    .replace(/,?\s*(?:con\s+)?\d+\s+unidades/gi, '')
    .replace(/,?\s*por\s+\d+(?:[.,]\d+)?\s*(?:mil|k|millones|millon)?/gi, '')
    .replace(/^[\s,;:"'-]+|[\s,;:"'-]+$/g, '')
    .trim();

  productName = namePart || 'Producto Nuevo';
  productName = productName.charAt(0).toUpperCase() + productName.slice(1);

} else if (
  lower.startsWith('agregar') || lower.startsWith('sumar') || lower.startsWith('poner') || lower.startsWith('añadir') || lower.startsWith('+')
) {
  action = 'ADJUST_STOCK';
  const m = rawMsg.match(/(?:agregar|sumar|poner|añadir|\+)\s*(?:(\d+)\s*(?:de\s+)?(?:stock|unidades)?|stock\s*(?:de\s+)?(\d+))\s*(?:a|al|para|en)?\s*(.+)$/i);
  if (m) {
    qtyChange = parseInt(m[1] || m[2], 10);
    productName = (m[3] || '').replace(/^[\s"']+|[\s"']+$/g, '').trim();
  } else {
    productName = rawMsg.replace(/^(?:agregar|sumar|poner|añadir|\+)(?:\s+stock)?\s+/i, '').replace(/^[\s"']+|[\s"']+$/g, '').trim();
    qtyChange = 5;
  }
} else if (
  lower.startsWith('restar') || lower.startsWith('quitar') || lower.startsWith('reducir') || lower.startsWith('descontar') || lower.startsWith('-')
) {
  action = 'ADJUST_STOCK';
  const m = rawMsg.match(/(?:restar|quitar|reducir|descontar|-)\s*(?:(\d+)\s*(?:de\s+)?(?:stock|unidades)?|stock\s*(?:de\s+)?(\d+))\s*(?:a|al|de|del|en)?\s*(.+)$/i);
  if (m) {
    qtyChange = -Math.abs(parseInt(m[1] || m[2], 10));
    productName = (m[3] || '').replace(/^[\s"']+|[\s"']+$/g, '').trim();
  } else {
    productName = rawMsg.replace(/^(?:restar|quitar|reducir|descontar|-)(?:\s+stock)?\s+/i, '').replace(/^[\s"']+|[\s"']+$/g, '').trim();
    qtyChange = -1;
  }
} else if (lower.includes('precio')) {
  action = 'UPDATE_PRICE';
  const m = rawMsg.match(/(?:cambiar|actualizar|modificar)?\s*precio\s*(?:de|del)?\s*(.+?)\s*(?:a|es|en|=|:)\s*(\d+(?:[.,]\d+)?\s*(?:mil|k|millones|millon)?(?:\s*pesos)?)$/i);
  if (m) {
    productName = (m[1] || '').replace(/^[\s"']+|[\s"']+$/g, '').trim();
    price = parseMoney(m[2]);
  }
} else if (lower.startsWith('eliminar') || lower.startsWith('borrar') || lower.startsWith('desactivar')) {
  action = 'DELETE';
  if (lower === 'eliminar todo' || lower === 'borrar todo') {
    productName = ''; // Delete all
  } else {
    productName = rawMsg
      .replace(/^(?:eliminar|borrar|desactivar)(?:\s+producto)?\s+/i, '')
      .replace(/^[\s"']+|[\s"']+$/g, '')
      .trim();
  }
}

// 2. Fallback to LLM if natural language couldn't be parsed
if (!action && rawOutput) {
  try {
    const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      action = parsed.action || 'LIST';
      productName = (parsed.product_name || '').trim();
      price = parseFloat(parsed.price || 0);
      stock = parseInt(parsed.stock || 0, 10);
      qtyChange = parsed.quantity_change || 0;
    }
  } catch(e) {}
}

if (!action) action = 'LIST';

return {
  action: action,
  product_name: productName,
  price: price,
  stock: stock,
  quantity_change: qtyChange,
  wa_number: norm.wa_number,
  tenant_id: norm.tenant_id,
  tenant_name: norm.tenant_name,
  whatsapp_phone_number_id: norm.whatsapp_phone_number_id,
  whatsapp_access_token: norm.whatsapp_access_token
};

const ctx = $('Code - Parse CRUD Intent').item.json;
const rawInput = $input.all().map(i => i.json);
const firstItem = rawInput[0] || {};
let message = '';
let buttons = [];

// Handle Ambiguity (>1 products match the search term)
if (firstItem.status === 'AMBIGUOUS') {
  const matches = firstItem.matched_products || [];
  const term = firstItem.search_term || ctx.product_name;
  const qty = firstItem.quantity_change;

  let actionText = 'aplicar esta acción';
  if (ctx.action === 'ADJUST_STOCK') {
    actionText = qty > 0 ? `sumar +${qty} unidades de stock` : `restar ${Math.abs(qty)} unidades de stock`;
  } else if (ctx.action === 'UPDATE_PRICE') {
    actionText = `cambiar el precio a $${ctx.price.toLocaleString('es-CO')} COP`;
  } else if (ctx.action === 'DELETE') {
    actionText = 'eliminar';
  }

  const listItems = matches.map((p, i) => `*${i + 1}. ${p.name}* (Stock: ${p.stock} un | $${parseFloat(p.price || 0).toLocaleString('es-CO')})`).join('\n');

  message = `❓ *ENCONTRÉ ${matches.length} PRODUCTOS CON "${term}"*\n\n` +
    `¿A cuál de ellos deseas ${actionText}?\n\n` +
    `${listItems}\n\n` +
    `👇 _Toca el botón correspondiente para confirmar la acción:_`;

  buttons = matches.slice(0, 3).map((p, i) => {
    let actionCommand = '';
    if (ctx.action === 'ADJUST_STOCK') {
      actionCommand = `agregar stock ${qty} a ${p.name}`;
    } else if (ctx.action === 'UPDATE_PRICE') {
      actionCommand = `cambiar precio de ${p.name} a ${ctx.price}`;
    } else {
      actionCommand = `eliminar producto ${p.name}`;
    }
    return {
      id: actionCommand,
      title: `${i + 1}. ${p.name.slice(0, 16)}`
    };
  });

  return {
    wa_number: ctx.wa_number,
    wa_message: message,
    buttons: buttons,
    phone_number_id: ctx.whatsapp_phone_number_id,
    access_token: ctx.whatsapp_access_token
  };
}

// Handle Not Found
if (firstItem.status === 'NOT_FOUND') {
  const active = firstItem.active_products || [];
  message = `❌ *No se encontró el producto: "${ctx.product_name}"*\n\n` +
    `💡 Revisa los productos que tienes disponibles actualmente:\n\n` +
    (active.length > 0 ? active.map((p, i) => `• *${p.name}* (Stock: ${p.stock})`).join('\n') : '_No tienes productos activos._');

  buttons = [
    { id: "ver inventario", title: "📦 Ver Inventario" },
    { id: "menu", title: "🏠 Menú Principal" }
  ];

  return {
    wa_number: ctx.wa_number,
    wa_message: message,
    buttons: buttons,
    phone_number_id: ctx.whatsapp_phone_number_id,
    access_token: ctx.whatsapp_access_token
  };
}

// Standard CRUD Formatter
switch (ctx.action) {
  case 'LIST': {
    const dbOut = rawInput.filter(p => p && p.id && p.name);
    if (!dbOut || dbOut.length === 0) {
      message = `📦 *INVENTARIO DE PRODUCTOS (0)*\n` +
        `🏢 *${ctx.tenant_name || 'Negocio'}*\n\n` +
        `_No tienes productos activos registrados en tu catálogo actualmente._\n\n` +
        `━━━━━━━━━━━━━━━━━━━━\n` +
        `✨ *¿CÓMO CREAR UN PRODUCTO?*\n` +
        `Escribe directamente un mensaje como:\n` +
        `👉 \`crear producto Camisa Azul precio 120000 stock 25\`\n` +
        `👉 \`crear producto Zapatos por 250 mil con 10 unidades\``;

      buttons = [
        { id: "tareas", title: "📋 Ver Tareas" },
        { id: "reporte", title: "📊 Ver Reporte" },
        { id: "menu", title: "🏠 Menú Principal" }
      ];
    } else if (dbOut.length === 1) {
      const p = dbOut[0];
      const stockStatus = p.stock === 0 ? ' ❌ *Agotado*' : (p.stock < 5 ? ' ⚠️ *Stock Bajo*' : ' ✅ *Disponible*');

      message = `📦 *INVENTARIO DE PRODUCTOS (1)*\n` +
        `🏢 *${ctx.tenant_name || 'Negocio'}*\n\n` +
        `*1. ${p.name}*\n` +
        `   💰 *Precio:* $${parseFloat(p.price || 0).toLocaleString('es-CO')} COP\n` +
        `   📊 *Stock:* ${p.stock} unidades (${stockStatus})\n\n` +
        `━━━━━━━━━━━━━━━━━━━━\n` +
        `👇 *Acciones rápidas 1-clic para este producto:*`;

      buttons = [
        { id: `agregar stock 5 a ${p.name}`, title: "➕ +5 Stock" },
        { id: `restar stock 1 a ${p.name}`, title: "➖ -1 Stock" },
        { id: `eliminar producto ${p.name}`, title: "🗑️ Eliminar" }
      ];
    } else {
      const items = dbOut.map((p, idx) => {
        const stockStatus = p.stock === 0 ? ' ❌ *Agotado*' : (p.stock < 5 ? ' ⚠️ *Stock Bajo*' : ' ✅ *Disponible*');
        return `*${idx + 1}. ${p.name}*\n` +
               `   💰 *Precio:* $${parseFloat(p.price || 0).toLocaleString('es-CO')} COP\n` +
               `   📊 *Stock:* ${p.stock} unidades (${stockStatus})`;
      }).join('\n\n');

      const firstProd = dbOut[0].name;

      message = `📦 *INVENTARIO DE PRODUCTOS (${dbOut.length})*\n` +
        `🏢 *${ctx.tenant_name || 'Negocio'}*\n\n` +
        `${items}\n\n` +
        `━━━━━━━━━━━━━━━━━━━━\n` +
        `💡 *ACCIONES RÁPIDAS:*\n` +
        `• ➕ *Sumar:* \`agregar 10 de stock a ${firstProd}\`\n` +
        `• ➖ *Restar:* \`restar 5 de stock a ${firstProd}\`\n` +
        `• 💲 *Precio:* \`cambiar precio de ${firstProd} a 450000\`\n` +
        `• 🗑️ *Eliminar:* \`eliminar ${firstProd}\`\n` +
        `• 🆕 *Crear:* \`crear producto <nombre> precio <precio> stock <cant>\``;

      buttons = [
        { id: `agregar stock 5 a ${firstProd}`, title: `➕ +5 a ${firstProd.slice(0, 10)}` },
        { id: `eliminar producto ${firstProd}`, title: `🗑️ Borrar ${firstProd.slice(0, 8)}` },
        { id: "menu", title: "🏠 Menú Principal" }
      ];
    }
    break;
  }
  case 'CREATE': {
    const created = rawInput[0] || {};
    const prodName = created.name || ctx.product_name;
    message = `✅ *PRODUCTO CREADO EXITOSAMENTE*\n\n` +
      `📦 *Nombre:* ${prodName}\n` +
      `💰 *Precio:* $${parseFloat(created.price || ctx.price || 0).toLocaleString('es-CO')} COP\n` +
      `📊 *Stock inicial:* ${created.stock !== undefined ? created.stock : ctx.stock} unidades\n\n` +
      `💡 _Tus clientes ya pueden buscar y comprar este producto en tu tienda._`;

    buttons = [
      { id: "ver inventario", title: "📦 Ver Inventario" },
      { id: `agregar stock 10 a ${prodName}`, title: "➕ Sumar +10 Stock" },
      { id: `eliminar producto ${prodName}`, title: "🗑️ Eliminar" }
    ];
    break;
  }
  case 'UPDATE_PRICE': {
    const updated = rawInput[0] || {};
    message = `✅ *PRECIO ACTUALIZADO EXITOSAMENTE*\n\n` +
      `📦 *Producto:* ${updated.name || ctx.product_name}\n` +
      `💰 *Nuevo Precio:* $${parseFloat(updated.new_price || ctx.price || 0).toLocaleString('es-CO')} COP`;

    buttons = [
      { id: "ver inventario", title: "📦 Ver Inventario" },
      { id: `agregar stock 5 a ${updated.name || ctx.product_name}`, title: "➕ Ajustar Stock" },
      { id: "menu", title: "🏠 Menú Principal" }
    ];
    break;
  }
  case 'DELETE': {
    const names = rawInput.filter(p => p.name).map(p => p.name).join(', ') || ctx.product_name;
    message = `🗑️ *PRODUCTO ELIMINADO CON ÉXITO*\n\n` +
      `Se ha retirado de tu catálogo activo: *${names}*.`;

    buttons = [
      { id: "ver inventario", title: "📦 Ver Inventario" },
      { id: "tareas", title: "📋 Ver Tareas" },
      { id: "menu", title: "🏠 Menú Principal" }
    ];
    break;
  }
  case 'ADJUST_STOCK': {
    const item = rawInput[0] || {};
    const prodName = item.name || ctx.product_name;
    const diff = ctx.quantity_change > 0 ? `+${ctx.quantity_change}` : `${ctx.quantity_change}`;

    message = `📊 *STOCK ACTUALIZADO EXITOSAMENTE*\n\n` +
      `📦 *Producto:* ${prodName}\n` +
      `🔄 *Ajuste aplicado:* ${diff} unidades\n` +
      `📈 *Nuevo Stock Total:* *${item.new_stock} unidades*`;

    buttons = [
      { id: "ver inventario", title: "📦 Ver Inventario" },
      { id: `agregar stock 5 a ${prodName}`, title: "➕ +5 Más" },
      { id: "menu", title: "🏠 Menú Principal" }
    ];
    break;
  }
  default:
    message = `ℹ️ Acción de catálogo completada.`;
    buttons = [
      { id: "ver inventario", title: "📦 Ver Inventario" },
      { id: "menu", title: "🏠 Menú Principal" }
    ];
}

return {
  wa_number: ctx.wa_number,
  wa_message: message,
  buttons: buttons,
  phone_number_id: ctx.whatsapp_phone_number_id,
  access_token: ctx.whatsapp_access_token
};

const ctx = $('Code - Parse CRUD Intent').item.json;
const rawProducts = $input.all().map(i => i.json).filter(p => p && p.id && p.name);
const target = (ctx.product_name || '').toLowerCase().trim();

let matched = [];

if (ctx.action === 'DELETE' && (!target || target === 'todo' || target === 'todos' || target === '%')) {
  // Delete all
  matched = rawProducts;
} else if (/^\d+$/.test(target)) {
  // Match by 1-based index (e.g. "1", "2")
  const idx = parseInt(target, 10) - 1;
  if (rawProducts[idx]) matched = [rawProducts[idx]];
} else if (target) {
  // Exact match first
  matched = rawProducts.filter(p => p.name.toLowerCase() === target);

  // Partial substring match if no exact match
  if (matched.length === 0) {
    matched = rawProducts.filter(p => {
      const pName = p.name.toLowerCase();
      return pName.includes(target) || target.includes(pName);
    });
  }
}

// Case 1: Ambiguity detected (>1 matches) for non-delete-all operations
if (matched.length > 1 && ctx.action !== 'DELETE') {
  return [{
    json: {
      status: 'AMBIGUOUS',
      action: ctx.action,
      search_term: ctx.product_name,
      matched_products: matched,
      quantity_change: ctx.quantity_change,
      new_price: ctx.price
    }
  }];
}

// Case 2: No match found
if (matched.length === 0) {
  return [{
    json: {
      status: 'NOT_FOUND',
      action: ctx.action,
      search_term: ctx.product_name,
      active_products: rawProducts
    }
  }];
}

// Case 3: Exactly 1 match (or multi-delete) -> Prepare updates
return matched.map(p => {
  let newStock = p.stock;
  let newPrice = p.price;
  let isActive = p.is_active;

  if (ctx.action === 'ADJUST_STOCK') {
    newStock = Math.max(0, parseInt(p.stock, 10) + ctx.quantity_change);
    isActive = newStock > 0 ? "true" : "true"; // Keep active
  } else if (ctx.action === 'UPDATE_PRICE') {
    newPrice = ctx.price;
  } else if (ctx.action === 'DELETE') {
    isActive = "false";
    newStock = 0;
  }

  return {
    json: {
      status: 'SUCCESS',
      id: p.id,
      name: p.name,
      old_stock: p.stock,
      new_stock: newStock,
      old_price: p.price,
      new_price: newPrice,
      is_active: isActive,
      action: ctx.action,
      quantity_change: ctx.quantity_change
    }
  };
});
